const SLACK_WEBHOOK_URL =
  'REPLACE_WITH_SLACK_WEBHOOK_URL';

const input = $input.first()?.json ?? {};
const body = input.body ?? input;

return [
  {
    json: {
      config: {
        companyName:
          body.companyName || 'ABM Solutions',

        senderName:
          body.senderName || 'Demo Sender',

        senderEmail:
          body.senderEmail || 'demo@example.com',

        slackWebhookUrl:
          body.slackWebhookUrl || SLACK_WEBHOOK_URL,

        crmUrl:
          body.crmUrl || 'https://www.hubspot.com/products/crm',

        dashboardUrl:
          body.dashboardUrl || 'https://lookerstudio.google.com/',

        retryWorkflowUrl:
          body.retryWorkflowUrl || 'https://example.com/configure-retry-webhook',

        demoMode:
          body.demoMode !== undefined
            ? body.demoMode
            : true
      },

      payload: body
    }
  }
];

const data = $input.first().json;
const event = data.event || {};

const severity = String(event.severity || 'medium').toLowerCase();

const severityConfig = {
  low: {
    emoji: 'ℹ️',
    label: 'LOW',
    color: '#36C5F0'
  },
  medium: {
    emoji: '⚠️',
    label: 'MEDIUM',
    color: '#ECB22E'
  },
  high: {
    emoji: '🚨',
    label: 'HIGH',
    color: '#E01E5A'
  },
  critical: {
    emoji: '🔥',
    label: 'CRITICAL',
    color: '#B00020'
  }
};

const selectedSeverity =
  severityConfig[severity] || severityConfig.medium;

const formattedTime = new Date().toLocaleString('en-US', {
  timeZone: 'America/Chicago',
  month: 'short',
  day: 'numeric',
  year: 'numeric',
  hour: 'numeric',
  minute: '2-digit',
  timeZoneName: 'short'
});

const title = event.title || 'Operational Notification';
const owner = event.owner || 'Unassigned';
const details = event.details || 'No additional details provided.';
const companyName = data.config?.companyName || 'ABM Solutions';

const fallbackText =
  `${selectedSeverity.emoji} ${selectedSeverity.label} ALERT: ${title}`;

const slackPayload = {
  text: fallbackText,
  attachments: [
    {
      color: selectedSeverity.color,
      blocks: [
        {
          type: 'header',
          text: {
            type: 'plain_text',
            text: `${selectedSeverity.emoji} ${selectedSeverity.label} PRIORITY ALERT`,
            emoji: true
          }
        },
        {
          type: 'section',
          text: {
            type: 'mrkdwn',
            text: `*${title}*`
          }
        },
        {
          type: 'section',
          fields: [
            {
              type: 'mrkdwn',
              text: `*Owner*\n${owner}`
            },
            {
              type: 'mrkdwn',
              text: `*Severity*\n${selectedSeverity.label}`
            }
          ]
        },
        {
          type: 'section',
          text: {
            type: 'mrkdwn',
            text: `*Details*\n${details}`
          }
        },
        {
          type: 'context',
          elements: [
            {
              type: 'mrkdwn',
              text: `🕒 ${formattedTime}`
            },
            {
              type: 'mrkdwn',
              text: `⚙️ Powered by ${companyName}`
            }
          ]
        },
        {
          type: 'actions',
          elements: [
            {
              type: 'button',
              text: {
                type: 'plain_text',
                text: '📂 Open CRM',
                emoji: true
              },
              style: 'primary',
              url: data.config.crmUrl
            },
            {
              type: 'button',
              text: {
                type: 'plain_text',
                text: '📊 Dashboard',
                emoji: true
              },
              url: data.config.dashboardUrl
            },
            {
              type: 'button',
              text: {
                type: 'plain_text',
                text: '🔄 Retry Workflow',
                emoji: true
              },
              url: data.config.retryWorkflowUrl
            }
          ]
        }
      ]
    }
  ]
};

return [
  {
    json: {
      ...data,
      slackPayload,
      result: {
        notificationPrepared: true,
        severity: selectedSeverity.label,
        event,
        buttons: {
          crm: data.config.crmUrl,
          dashboard: data.config.dashboardUrl,
          retry: data.config.retryWorkflowUrl
        }
      }
    }
  }
];
